import sys
input = sys.stdin.read

def main():
    data = input().split()
    n = int(data[0])
    segments = []
    idx = 1
    for _ in range(n):
        x1 = int(data[idx])
        y1 = int(data[idx+1])
        x2 = int(data[idx+2])
        y2 = int(data[idx+3])
        idx += 4
        if x1 == x2:
            # vertical segment
            segments.append(('v', x1, min(y1, y2), max(y1, y2)))
        else:
            # horizontal segment
            segments.append(('h', y1, min(x1, x2), max(x1, x2)))

    # For vertical segments, collect all y ranges
    v_segments = []
    for seg in segments:
        if seg[0] == 'v':
            v_segments.append((seg[1], seg[2], seg[3]))

    # For horizontal segments, collect all x ranges
    h_segments = []
    for seg in segments:
        if seg[0] == 'h':
            h_segments.append((seg[1], seg[2], seg[3]))

    # Merge vertical segments
    v_segments.sort()
    merged_v = []
    for seg in v_segments:
        if not merged_v:
            merged_v.append(seg)
        else:
            last = merged_v[-1]
            if seg[1] <= last[2] + 1:
                # overlap or adjacent, merge
                new_start = last[0]
                new_end = max(last[2], seg[2])
                merged_v[-1] = (new_start, new_end)
            else:
                merged_v.append(seg)

    # Merge horizontal segments
    h_segments.sort()
    merged_h = []
    for seg in h_segments:
        if not merged_h:
            merged_h.append(seg)
        else:
            last = merged_h[-1]
            if seg[1] <= last[2] + 1:
                # overlap or adjacent, merge
                new_start = last[0]
                new_end = max(last[2], seg[2])
                merged_h[-1] = (new_start, new_end)
            else:
                merged_h.append(seg)

    # Count unique cells
    visited = set()

    # Process vertical segments
    for (x, y1, y2) in merged_v:
        for y in range(y1, y2 + 1):
            visited.add((x, y))

    # Process horizontal segments
    for (y, x1, x2) in merged_h:
        for x in range(x1, x2 + 1):
            visited.add((x, y))

    print(len(visited))

main()

