import sys

def main():
    n = int(sys.stdin.readline())
    males = []
    females = []
    for _ in range(n):
        parts = sys.stdin.readline().split()
        gender = parts[0]
        a = int(parts[1])
        b = int(parts[2])
        if gender == 'M':
            males.append((a, b))
        else:
            females.append((a, b))

    max_people = 0
    for day in range(1, 367):
        m_count = 0
        f_count = 0
        for a, b in males:
            if a <= day <= b:
                m_count += 1
        for a, b in females:
            if a <= day <= b:
                f_count += 1
        current = min(m_count, f_count) * 2
        if current > max_people:
            max_people = current
    print(max_people)

main()

