import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])

    t_blocks = []
    idx = 2
    for _ in range(n):
        l = int(data[idx])
        c = data[idx + 1]
        t_blocks.append((l, c))
        idx += 2

    s_blocks = []
    for _ in range(m):
        l = int(data[idx])
        c = data[idx + 1]
        s_blocks.append((l, c))
        idx += 2

    # Convert compressed blocks to actual string
    def compress_to_string(blocks):
        res = []
        for l, c in blocks:
            res.append(c * l)
        return ''.join(res)

    t_str = compress_to_string(t_blocks)
    s_str = compress_to_string(s_blocks)

    # Use KMP to find occurrences of s_str in t_str
    def kmp_failure_function(pattern):
        m = len(pattern)
        fail = [0] * m
        j = 1
        while j < m:
            if pattern[j] == pattern[fail[j]]:
                fail[j] = fail[j - 1] + 1
                j += 1
            else:
                if fail[j - 1] == 0:
                    fail[j] = 0
                    j += 1
                else:
                    j = fail[j - 1] + 1
        return fail

    def kmp_search(text, pattern, fail):
        i = 0  # index for text
        j = 0  # index for pattern
        count = 0
        while i < len(text):
            if pattern[j] == text[i]:
                i += 1
                j += 1
            if j == len(pattern):
                count += 1
                j = fail[j - 1]
            elif i < len(text) and pattern[j] != text[i]:
                if j != 0:
                    j = fail[j - 1]
                else:
                    i += 1
        return count

    if len(s_str) > len(t_str):
        print(0)
        return

    fail = kmp_failure_function(s_str)
    print(kmp_search(t_str, s_str, fail))

if __name__ == "__main__":
    main()

