from collections import Counter

def main():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    count = Counter(a)

    max_len = 2

    for i in range(n):
        for j in range(i + 1, n):
            f0 = a[i]
            f1 = a[j]
            next_val = f0 + f1
            cnt = 2
            valid = True
            for k in range(2, n):
                if count[next_val] > 0:
                    count[next_val] -= 1
                    cnt += 1
                    f0, f1 = f1, next_val
                    next_val = f0 + f1
                else:
                    valid = False
                    break
            if valid:
                max_len = max(max_len, cnt)
            # restore counts
            if valid:
                count[next_val] += 1
            else:
                count[next_val] = 0

    print(max_len)

