import sys
from itertools import product

def main():
    s = sys.stdin.readline().strip()
    parts = s.split('=')
    left = parts[0].split()
    right = int(parts[1])
    n = right

    ops = ['+', '-', '+', '+']
    if len(left) == 5:
        ops = ['+', '-', '+', '+']
    elif len(left) == 4:
        ops = ['+', '-', '+']
    elif len(left) == 3:
        ops = ['+', '-']
    elif len(left) == 2:
        ops = ['-']

    variables = []
    for i in range(len(left)):
        if left[i] == '?':
            variables.append(i)

    total_vars = len(variables)
    max_val = n

    for nums in product(range(1, max_val + 1), repeat=total_vars):
        expr = []
        val = 0
        for i in range(len(left)):
            if left[i] == '?':
                expr.append(str(nums[variables.index(i)]))
            else:
                expr.append(left[i])
            if i > 0 and (i % 2 == 1 or i == 0):
                expr.append(ops[i // 2 - 1])
        expr_str = ' '.join(expr)
        try:
            result = eval(expr_str)
