import sys

def main():
    m = int(sys.stdin.readline())

    def get_max_blocks(x):
        blocks = []
        while x > 0:
            a = int(x ** (1/3))
            while a ** 3 > x:
                a -= 1
            blocks.append(a)
            x -= a ** 3
        return len(blocks), sum(a**3 for a in blocks)

    max_blocks = 0
    best_x = 0

    # Try all possible X from 1 to m
    for x in range(1, m + 1):
        b, total = get_max_blocks(x)
        if b > max_blocks or (b == max_blocks and total > best_x):
            max_blocks = b
            best_x = total

    print(max_blocks, best_x)

main()

