import sys
input = sys.stdin.read

def main():
    data = input().split()
    n = int(data[0])
    m = int(data[1])
    edges = []
    idx = 2
    for _ in range(m):
        u = int(data[idx]) - 1
        v = int(data[idx + 1]) - 1
        edges.append((u, v))
        idx += 2

    # Check if the graph is bipartite
    color = [-1] * n
    is_bipartite = True
    from collections import deque
    for i in range(n):
        if color[i] == -1:
            queue = deque()
            queue.append(i)
            color[i] = 0
            while queue:
                u = queue.popleft()
                for v, _ in edges:
                    if v == u:
                        continue
                    if color[v] == -1:
                        color[v] = color[u] ^ 1
                        queue.append(v)
                    elif color[v] == color[u]:
                        is_bipartite = False
                        break
                if not is_bipartite:
                    break
            if not is_bipartite:
                break

    if not is_bipartite:
        print(-1)
        return

    # If it's bipartite, then one part is a vertex cover
    # Because in bipartite graphs, one of the partitions is a vertex cover
    # So we can take one partition as A and the other as B (if they are non-empty)
    # But we need to ensure that both are non-empty
    part0 = []
    part1 = []
    for i in range(n):
        if color[i] == 0:
            part0.append(i + 1)
        else:
            part1.append(i + 1)

    if len(part0) == 0 or len(part1) == 0:
        print(-1)
        return

    # Check if both parts are vertex covers
    # For part0: check if every edge has at least one endpoint in part0
    # For part1: check if every edge has at least one endpoint in part1
    def is_vertex_cover(part):
        for u, v in edges:
            if u not in part and v not in part:
                return False
        return True

    if is_vertex_cover(part0) and is_vertex_cover(part1):
        print(len(part0))
        print(' '.join(map(str, part0)))
        print(len(part1))
        print(' '.join(map(str, part1)))
    else:
        print(-1)

main()

