from collections import defaultdict

def main():
    input = sys.stdin.read
    data = input().splitlines()
    t = int(data[0])
    operations = data[1:t+1]

    multiset = defaultdict(int)
    pattern_map = defaultdict(int)

    for op in operations:
        parts = op.split()
        if parts[0] == '+':
            ai = int(parts[1])
            multiset[ai] += 1
        elif parts[0] == '-':
            ai = int(parts[1])
            multiset[ai] -= 1
        else:
            s = parts[1]
            # Convert the pattern to a binary representation of parity
            # For each digit in the number, check if it is even or odd
            # We need to generate a key for the pattern
            # The pattern is up to 18 digits long
            # So we can represent it as a tuple of 18 bits (0 or 1)
            pattern_key = []
            for i in range(18):
                if i < len(s):
                    pattern_key.append(int(s[i]))
                else:
                    pattern_key.append(0)
            pattern_key = tuple(pattern_key)
            # Now, for each number in the multiset, check if it matches the pattern
            count = 0
            for num in multiset:
                # Convert the number to a string with leading zeros to make it 18 digits
                num_str = str(num).zfill(18)
                # Check each digit's parity
                match = True
                for i in range(18):
                    if (i + 1) > len(num_str):
                        num_digit = 0
                    else:
                        num_digit = int(num_str[-(i + 1)])
                    if num_digit % 2 == 0:
                        expected = 0
                    else:
                        expected = 1
                    if expected != pattern_key[i]:
                        match = False
                        break
                if match:
                    count += multiset[num]
            print(count)

if __name__ == "__main__":
    main()

