import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    p = int(data[1])
    s = int(data[2])

    a = list(map(int, data[3:3+n]))
    b = list(map(int, data[3+n:3+2*n]))

    students = list(range(n))

    # Sort students by a + b in descending order
    students.sort(key=lambda x: a[x] + b[x], reverse=True)

    # Select top p students for programming team (based on a)
    prog_team = []
    sports_team = []

    for i in range(n):
        if len(prog_team) < p and len(sports_team) < s:
            if a[students[i]] > a[students[0]]:
                prog_team.append(students[i])
            else:
                sports_team.append(students[i])
        elif len(prog_team) < p:
            prog_team.append(students[i])
        elif len(sports_team) < s:
            sports_team.append(students[i])

    # If not enough students selected, adjust
    while len(prog_team) < p:
        for i in range(n):
            if students[i] not in prog_team and students[i] not in sports_team:
                prog_team.append(students[i])
                break

    while len(sports_team) < s:
        for i in range(n):
            if students[i] not in prog_team and students[i] not in sports_team:
                sports_team.append(students[i])
                break

    # Calculate total strength
    total_strength = sum(a[i] for i in prog_team) + sum(b[i] for i in sports_team)

    # Output
    print(total_strength)
    print(' '.join(map(str, [i+1 for i in prog_team])))
    print(' '.join(map(str, [i+1 for i in sports_team])))

if __name__ == "__main__":
    main()

