def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    m = int(data[n+1])
    b = list(map(int, data[n+2:]))

    # dp[i][j] represents the length of the longest common increasing subsequence
    # ending with a[i] and b[j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # For each element in a, we check all elements in b
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                # Check all previous elements in a and b to find the maximum length
                max_len = 0
                for k in range(i):
                    if a[k] < a[i - 1]:
                        max_len = max(max_len, dp[k][j - 1])
                dp[i][j] = max_len + 1
            else:
                # Check all previous elements in a and b to find the maximum length
                max_len = 0
                for k in range(i):
                    for l in range(j):
                        if a[k] < a[i - 1] and b[l] < b[j - 1]:
                            max_len = max(max_len, dp[k][l])
                dp[i][j] = max_len

    # Find the maximum value in dp
    max_len = 0
    for i in range(n + 1):
        for j in range(m + 1):
            if dp[i][j] > max_len:
                max_len = dp[i][j]

    # Reconstruct the sequence
    result = []
    for i in range(n, 0, -1):
        for j in range(m, 0, -1):
            if dp[i][j] == max_len and a[i - 1] == b[j - 1]:
                result.append(a[i - 1])
                max_len -= 1
                break

    print(len(result))
    print(' '.join(map(str, reversed(result))))

