import re

def process_text(text):
    # Split the text into tokens (words and punctuation)
    tokens = re.findall(r'\w+|[^\w\s]', text)

    result = []
    for token in tokens:
        if token in ['.', ',', '!', '?']:
            result.append(token)
        else:
            if result and not (result[-1] in ['.', ',', '!', '?']):
                result.append(' ')
            result.append(token)

    # Remove any extra space at the end
    return ''.join(result).rstrip()

