import sys
import math

def main():
    n = int(sys.stdin.readline())
    moves = sys.stdin.readline().strip()

    # Directions: (dx, dy)
    directions = {
        'L': (-1, 0),
        'R': (1, 0),
        'U': (0, 1),
        'D': (0, -1)
    }

    # Possible directions for each move
    possible_moves = []
    for c in moves:
        if c == 'U':
            possible_moves.append(['U'])
        elif c == 'D':
            possible_moves.append(['D'])
        elif c == 'L':
            possible_moves.append(['L'])
        elif c == 'R':
            possible_moves.append(['R'])
        else:
            # For 'UL', 'UR', 'DL', 'DR'
            if c == 'UL':
                possible_moves.append(['U', 'L'])
            elif c == 'UR':
                possible_moves.append(['U', 'R'])
            elif c == 'DL':
                possible_moves.append(['D', 'L'])
            elif c == 'DR':
                possible_moves.append(['D', 'R'])

    # We'll use BFS to track all possible positions
    from collections import deque

    # Start from the end point (0, 0) and work backwards
    # Each step is a reverse of the possible moves
    # So for each move, we can go back in reverse direction
    # For example, if the original move was 'U', then reverse is 'D'

    # Initialize with (0, 0)
    visited = set()
    queue = deque()
    queue.append((0, 0))
    visited.add((0, 0))

    for i in range(n-1, -1, -1):
        next_queue = deque()
        for x, y in queue:
            for move in possible_moves[i]:
                dx, dy = directions[move]
                nx, ny = x + dx, y + dy
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    next_queue.append((nx, ny))
        queue = next_queue

    print(len(visited))

if __name__ == "__main__":
    main()

