import math

def is_t_prime(x):
    if x < 1:
        return False
    if x == 1:
        return False
    # Find the square root of x
    sqrt_x = int(math.isqrt(x))
    # Check if x is a perfect square
    if sqrt_x * sqrt_x != x:
        return False
    # Check if sqrt_x is a prime
    if sqrt_x < 2:
        return False
    for i in range(2, int(math.isqrt(sqrt_x)) + 1):
