    # Each new triangle adds 1 more triangle
    # So we can create a complete graph of size m, which has C(m, 3) triangles
    # Find the smallest m such that C(m, 3) >= k
    m = 3
    while (m * (m - 1) * (m - 2)) // 6 < k:
        m += 1

