def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    q = list(map(int, data[2:2+n]))
    s = list(map(int, data[2+n:2+2*n]))

    from collections import deque

    # Precompute the inverse of permutation q
    inv_q = [0] * (n + 1)
    for i in range(n):
        inv_q[q[i]] = i + 1

    # Function to apply permutation q to a permutation p
    def apply(q, p):
        return [p[q[i] - 1] for i in range(n)]

    # Function to apply inverse of permutation q to a permutation p
    def apply_inv(q, p):
        return [p[inv_q[i] - 1] for i in range(n)]

    # BFS to find if s can be reached in exactly k steps without appearing before
    visited = set()
    queue = deque()
    queue.append(([]))
    visited.add(tuple([]))

    while queue:
        path = queue.popleft()
        if len(path) == k:
            if tuple(apply(q, apply(q, [i for i in range(1, n+1)]))) == tuple(s):
                print("YES")
                return
            else:
                continue
        for move in [0, 1]:
            new_path = path + [move]
            if len(new_path) > k:
                continue
            current = [i for i in range(1, n+1)]
            for m in new_path:
                if m == 0:
                    current = apply(q, current)
                else:
                    current = apply_inv(q, current)
            if tuple(current) not in visited:
                visited.add(tuple(current))
                queue.append(new_path)

    print("NO")

if __name__ == "__main__":
    main()

