import math
import sys

def main():
    n = int(sys.stdin.readline())
    points = [tuple(map(int, sys.stdin.readline().split())) for _ in range(n)]

    angles = []
    for x, y in points:
        if x == 0 and y == 0:
            continue
        angle = math.atan2(y, x)
        angles.append(angle)

    angles.sort()
    min_angle = angles[1] - angles[0]
    for i in range(2, len(angles)):
        current = angles[i] - angles[i-1]
        if current < min_angle:
            min_angle = current

    print(f"{min_angle * 180 / math.pi:.10f}")

if __name__ == "__main__":
    main()

