                used_c -= 1
                letter = chr(ord(letter) + 1)
            else:
                break

    # Fill with 1x2 planks horizontally
    for i in range(n):
        for j in range(0, m, 2):
            if a > 0:
                for k in range(j, j + 2):
                    grid[i][k] = letter
                a -= 1
                letter = chr(ord(letter) + 1)
            else:
                break

    # Fill with 2x1 planks vertically
    for j in range(m):
        for i in range(0, n, 2):
            if b > 0:
                for k in range(i, i + 2):
                    grid[k][j] = letter
                b -= 1
                letter = chr(ord(letter) + 1)
            else:
                break

    # If not all area is filled, it's impossible
    filled = sum(row.count('') for row in grid)
    if filled > 0:
        print("IMPOSSIBLE")
        return

    # Print the grid
    for row in grid:
        print(''.join(row))

