import sys
import math

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    m = int(data[1])
    nails = []
    idx = 2
    for _ in range(n):
        x = int(data[idx])
        y = int(data[idx+1])
        nails.append((x, y))
        idx += 2
    rods = list(map(int, data[idx:idx+m]))

    rod_len = [0] * m
    for i in range(m):
        rod_len[i] = rods[i]

    used = [False] * m
    res = [-1] * n

    def dist(p1, p2):
        return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

    for i in range(n):
        if i % 2 == 0:
            p1 = nails[i]
            p2 = nails[(i + 1) % n]
            d = dist(p1, p2)
            for j in range(m):
                if not used[j] and rod_len[j] >= d:
                    used[j] = True
                    res[i] = j + 1
                    break
        else:
            pass

    for i in range(n):
        if res[i] == -1:
            print("NO")
            return

    print("YES")
    print(' '.join(map(str, res)))

if __name__ == "__main__":
    main()

