import sys

def main():
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    intervals = []
    for i in range(n):
        l = int(data[1 + 2 * i])
        r = int(data[2 + 2 * i])
        intervals.append((l, r, i + 1))  # (start, end, index)

    def is_valid(intervals, exclude_index):
        new_intervals = [interval for i, interval in enumerate(intervals) if i != exclude_index]
        new_intervals.sort()
        for i in range(1, len(new_intervals)):
            if new_intervals[i][0] < new_intervals[i - 1][1]:
                return False
        return True

    result = []
    for i in range(n):
        if is_valid(intervals, i):
            result.append(intervals[i][2])

    print(len(result))
    if result:
        print(' '.join(map(str, sorted(result))))

main()

