pass@1:
import sys

def main():
    chat = set()
    total_traffic = 0
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        if line.startswith('+'):
            name = line[1:]
            chat.add(name)
        elif line.startswith('-'):
            name = line[1:]
            chat.discard(name)
        else:
            parts = line.split(':', 1)
            if len(parts) != 2:
                continue
            sender, message = parts
            if sender in chat:
                total_traffic += len(message) * len(chat)
    print(total_traffic)

if __name__ == "__main__":
    main()

