def main():
    data = input().split()
    n = int(data[0])
    h = list(map(int, data[1:]))

    if n == 1:
        print(0)
        return

    # For each hill, find the next greater to the right and left
    next_greater = [n] * n
    prev_greater = [n] * n

    stack = []
    for i in range(n):
        while stack and h[stack[-1]] < h[i]:
            next_greater[stack.pop()] = i
        stack.append(i)

    stack = []
    for i in range(n-1, -1, -1):
        while stack and h[stack[-1]] < h[i]:
            prev_greater[stack.pop()] = i
        stack.append(i)

    res = 0
    for i in range(n):
        if next_greater[i] != n:
            res += 1
        if prev_greater[i] != n:
            res += 1

    print(res // 2)

main()

