import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    a = list(map(float, data[2:2 + n]))

    total = sum(a)
    if k == 100:
        print("{0:.9f}".format(total / n))
        return

    def possible(m):
        needed = 0
        for x in a:
            if x > m:
                needed += (x - m) * (100 - k) / k
        return needed <= total

    low = 0.0
    high = max(a)

    for _ in range(100):
        mid = (low + high) / 2
        if possible(mid):
            low = mid
        else:
            high = mid

    print("{0:.9f}".format(low))

if __name__ == "__main__":
    main()

