n, m, k, t = map(int, input().split())
waste = set()
for _ in range(k):
    a, b = map(int, input().split())
    waste.add((a, b))
for _ in range(t):
    i, j = map(int, input().split())
    if (i, j) in waste:
        print("Waste")
    else:
        pos = 0
        for row in range(1, n + 1):
            for col in range(1, m + 1):
                if (row, col) == (i, j):
                    break
                if (row, col) not in waste:
                    pos += 1
        if pos % 3 == 0:
            print("Grapes")
        elif pos % 3 == 1:
            print("Carrots")
        else:
            print("Kiwis")

