import sys
import math

def main():
    n = int(sys.stdin.readline())
    if n == 1:
        print("0/1")
        return

    from fractions import Fraction

    def expected(n):
        if n == 1:
            return Fraction(0, 1)
        if n == 2:
            return Fraction(1, 1)
        if n == 4:
            return Fraction(2, 1)

        # Use dynamic programming to compute the expected value
        dp = [Fraction(0, 1) for _ in range(n + 1)]
        for i in range(2, n + 1):
            # Try to find the smallest k such that 2^k >= i
            k = 0
            while (1 << k) < i:
                k += 1
            # The number of possible outcomes is 2^k
            # We can assign each of the first i knights to a group
            # and repeat until we get a valid outcome
            # The expected value is sum_{j=1}^{k} (probability of stopping at j) * j
            total = Fraction(0, 1)
            for j in range(1, k + 1):
                ways = 1 << j
                prob = Fraction(1, ways)
                count = 0
                for m in range(1, i + 1):
                    if m <= ways:
                        count += 1
                    else:
                        break
                total += prob * j
            dp[i] = total
        return dp[n]

    result = expected(n)
    print(f"{result.numerator}/{result.denominator}")

if __name__ == "__main__":
    main()

