import math

def main():
    n = int(sys.stdin.readline())
    if n == 1:
        print("0/1")
        return

    numerator = 0
    denominator = 1

    for i in range(1, n + 1):
        if i % 2 == 1:
            numerator += 2 ** (i - 1)
        else:
            numerator += 2 ** (i - 1) * (i // 2)

    gcd_val = math.gcd(numerator, denominator)
    numerator //= gcd_val
    denominator //= gcd_val

    print(f"{numerator}/{denominator}")

if __name__ == "__main__":
    main()

