import sys

def can_divide_array(n, a):
    total = sum(a)
    prefix_sum = 0
    for i in range(n):
        prefix_sum += a[i]
        if (total - prefix_sum) % 2 == 0:
            # Check if we can move one element to make the two parts equal
            remaining = (total - prefix_sum) // 2
            # Try moving a[i] to the end
            if (prefix_sum - a[i]) == remaining and (remaining + a[i]) == total - prefix_sum:
                return "YES"
            # Try moving a[i+1] to the beginning
            if (prefix_sum + a[i+1]) == remaining and (remaining - a[i+1]) == prefix_sum - a[i]:
                return "YES"
            # Try moving a[i] to somewhere else
            if (prefix_sum - a[i]) == remaining and (remaining + a[i]) == total - prefix_sum:
                return "YES"
            # Try moving a[i+1] to somewhere else
            if (prefix_sum + a[i+1]) == remaining and (remaining - a[i+1]) == prefix_sum - a[i]:
                return "YES"
    return "NO"

def main():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))
    print(can_divide_array(n, a))

if __name__ == "__main__":
    main()

