def circle_area(x1, y1, r1, x2, y2, r2):
    dx = x1 - x2
    dy = y1 - y2
    dist = math.hypot(dx, dy)
    if dist > r1 + r2:
        return 0.0
    if dist + min(r1, r2) < max(r1, r2):
        return 0.0
    if dist == 0 and r1 == r2:
        return 0.0
    if dist == 0:
