    start_idx = positions.index(start)
    end_idx = positions.index(end)

    # Clockwise direction: each second moves +1 (mod 4)
    # Counter-clockwise direction: each second moves -1 (mod 4)
    # Check both possibilities

    if (start_idx + n) % 4 == end_idx:
        cw = True
    else:
        cw = False

    if (start_idx - n) % 4 == end_idx:
        ccw = True
    else:
        ccw = False

    if cw and ccw:
        print("undefined")
    elif cw:
        print("cw")
    else:
        print("ccw")

